    "date": "ปี พ.ศ. 2565",
    "title": "สำนักวิทยบริการและเทคโนโลยีสารสนเทศ ร่วมกับคณะวิทยาศาสตร์และเทคโนโลยี มสด. จัดอบรมหลักสูตรการวิเคราะห์ข้อมูลและการนำเสนอข้อมูลด้วยภาพ (Data Analytics and Data Visualization)",
    "context": "สำนักวิทยบริการและเทคโนโลยีสารสนเทศ ร่วมกับคณะวิทยาศาสตร์และเทคโนโลยี มหาวิทยาลัยสวนดุสิต ซึ่งเป็นเครือข่ายความร่วมมือเพื่อการพัฒนาทักษะด้านดิจิทัลสำหรับข้าราชการและบุคลากรภาครัฐของสถาบันพัฒนาบุคลากรภาครัฐด้านดิจิทัล (TDGA) ภายใต้การดำเนินงานของสำนักงานพัฒนารัฐบาลดิจิทัล (องค์การมหาชน) (DGA) จัดอบรม...",
    "what": "สำนักวิทยบริการและเทคโนโลยีสารสนเทศ ร่วมกับคณะวิทยาศาสตร์และเทคโนโลยี มสด. จัดอบรมหลักสูตรการวิเคราะห์ข้อมูลและการนำเสนอข้อมูลด้วยภาพ (Data Analytics and Data Visualization)",
