    "context": "มหาวิทยาลัยสวนดุสิต โดย ผศ.ดร. วิชชา&nbsp; ฉิมพลี&nbsp; คณบดีคณะวิทยาศาสตร์และเทคโนโลยี ลงนามความร่วมมือทางวิชาการกับ บริษัท ซีเชอร์ จำกัด&nbsp; ซึ่งได้รับเกียรติจาก นายชัยธนา &nbsp;ไชยมงคล กรรมการผู้จัดการบริษัท เป็นประธานร่วมลงนาม&nbsp; เพื่อสร้างเครือข่ายบริการวิชาการแก่สาธารณชนผู้สนใจในการจัดอบร...",
