    "date": "ปี พ.ศ. 2559",
    "title": "คณะวิทยาศาสตร์และเทคโนโลยี มสด.จัดโครงการอบรมเชิงปฏิบัติการจัดการเรียนรู้ตามแนวทางสะเต็มศึกษา",
    "context": "คณะวิทยาศาสตร์และเทคโนโลยี มหาวิทยาลัยสวนดุสิต จัดโครงการอบรมเชิงปฏิบัติการจัดการเรียนรู้ตามแนวทางสะเต็มศึกษาให้กับครู 130 คน จาก 39 โรงเรียน ในเขตกรุงเทพและปริมณฑล โดยได้รับเกียรติจาก รศ.ดร.ศิโรจน์ ผลพันธิน อธิการบดีมหาวิทยาลัยสวนดุสิต เป็นประธานเปิดการอบรมและบรรยายพิเศษ กล่าวรายงานโดย ดร.วิชชา ฉิม...",
    "what": "คณะวิทยาศาสตร์และเทคโนโลยี มสด.จัดโครงการอบรมเชิงปฏิบัติการจัดการเรียนรู้ตามแนวทางสะเต็มศึกษา",
