    "date": "ปี พ.ศ. 2559",
    "title": "คณะวิทยาศาสตร์และเทคโนโลยี ร่วมกับ สสวท. เปิดศูนย์สะเต็มศึกษาและอบรมเชิงปฏิบัติการสะเต็มศึกษา (STEM Education)",
    "context": "คณะวิทยาศาสตร์และเทคโนโลยี ร่วมกับ สถาบันส่งเสริมการสอนวิทยาศาสตร์และเทคโนโลยี (สสวท .) พิธีเปิดศูนย์สะเต็มศึกษาและอบรมเชิงปฏิบัติการสะเต็มศึกษา (STEM Education) โดยมี ดร.สิทธิพร เอี่ยมเสน คณบดีคณะครุศาสตร์ ให้เกียรติเป็นประธานเปิดงาน กล่าวรายงานโดย ดร.วิชชา ฉิมพลี คณบดีคณะวิทยาศาสตร์และเทคโนโลยี ดร...",
    "what": "คณะวิทยาศาสตร์และเทคโนโลยี ร่วมกับ สสวท. เปิดศูนย์สะเต็มศึกษาและอบรมเชิงปฏิบัติการสะเต็มศึกษา (STEM Education)",
