    "date": "ปี พ.ศ. 2558",
    "title": "ศูนย์สิ่งแวดล้อม จัดกิจกรรมเสวนา KM Sharing  หัวข้อ&#8221;การมุ่งสู่ความเป็นเลิศด้านการเป็นหน่วยฝึกอบรมระบบคุณภาพและการเรียนการสอนเชิงปฏิบัติการด้านสิ่งแวดล้อม&#8221;",
